import { useState, useMemo, type FormEvent } from 'react';
import { Plus, Edit2, Trash2, Search, ChevronLeft, ChevronRight, Loader2, Eye, EyeOff, Languages, Upload, Globe, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import I18nInput from '@/components/I18nInput';
import RichTextEditor from '@/components/RichTextEditor';
import { useBlog, type IBlogArticle } from '@/hooks/useBlog';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { batchTranslateI18n } from '@/lib/translate';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';
import { imgPath } from '@/utils/img-path';
import { compressImage } from '@/utils/compress-image';
import { Image } from '@/components/ui/image';

interface BlogForm {
  slug: string;
  coverImage: string;
  title: I18nText;
  summary: I18nText;
  content: I18nText;
  metaTitle: I18nText;
  metaDescription: I18nText;
  category: string;
  publishDate: string;
  published: boolean;
  order: number;
}

const emptyForm = (): BlogForm => ({
  slug: '',
  coverImage: '',
  title: createI18nText(''),
  summary: createI18nText(''),
  content: createI18nText(''),
  metaTitle: createI18nText(''),
  metaDescription: createI18nText(''),
  category: 'Guide',
  publishDate: new Date().toISOString().split('T')[0],
  published: true,
  order: 0,
});

const PAGE_SIZE = 10;

export default function AdminBlogPage() {
  const { articles, addArticle, updateArticle, deleteArticle, loading } = useBlog();
  const { adminT } = useI18n();
  const { markDirty, syncModule, syncJsonFile, syncImagesInData, syncImagesInHtml, getStatus } = useSyncService();
  const syncStatus = getStatus('blog');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<BlogForm>(emptyForm());
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [translating, setTranslating] = useState(false);
  const [batchTranslating, setBatchTranslating] = useState(false);
  const [batchTranslateProgress, setBatchTranslateProgress] = useState({ current: 0, total: 0 });

  const filteredArticles = useMemo(() => {
    let list = [...articles];
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      list = list.filter(
        (a) =>
          a.slug.toLowerCase().includes(q) ||
          a.title.en.toLowerCase().includes(q) ||
          a.title.zh.toLowerCase().includes(q)
      );
    }
    return list;
  }, [articles, searchQuery]);

  const totalPages = Math.max(1, Math.ceil(filteredArticles.length / PAGE_SIZE));
  const paginatedArticles = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredArticles.slice(start, start + PAGE_SIZE);
  }, [filteredArticles, currentPage]);

  const resetForm = () => {
    setForm(emptyForm());
    setEditingId(null);
  };

  const openCreate = () => {
    resetForm();
    setDialogOpen(true);
  };

  const openEdit = (article: IBlogArticle) => {
    setForm({
      slug: article.slug,
      coverImage: article.coverImage,
      title: article.title,
      summary: article.summary,
      content: article.content,
      category: article.category,
      metaTitle: article.metaTitle,
      metaDescription: article.metaDescription,
      publishDate: article.publishDate,
      published: article.published,
      order: article.order,
    });
    setEditingId(article.id);
    setDialogOpen(true);
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    if (!form.slug.trim()) {
      toast.error('Please enter the SEO slug');
      return;
    }
    if (!form.title.en.trim()) {
      toast.error('Please enter the English title');
      return;
    }

    try {
      if (editingId) {
        updateArticle(editingId, form);
        markDirty('blog');
        toast.success('Article updated successfully');
      } else {
        if (articles.some((a) => a.slug === form.slug)) {
          toast.error('Slug already exists, please use a unique slug');
          return;
        }
        addArticle(form);
        markDirty('blog');
        toast.success('Article added successfully');
      }
      setDialogOpen(false);
      resetForm();
    } catch (err) {
      toast.error('Failed to save article: ' + (err instanceof Error ? err.message : String(err)));
    }
  };

  const handleDelete = () => {
    if (!deleteId) return;
    try {
      deleteArticle(deleteId);
      markDirty('blog');
      toast.success('Article deleted');
    } catch {
      toast.error('Failed to delete article');
    }
    setDeleteId(null);
  };

  const togglePublished = (id: string, published: boolean) => {
    try {
      updateArticle(id, { published });
      markDirty('blog');
      toast.success(published ? 'Article published' : 'Article unpublished');
    } catch {
      toast.error('Failed to update status');
    }
  };

  const handleTranslate = async () => {
    if (!form.title.en.trim()) {
      toast.error('Please enter English content first');
      return;
    }
    setTranslating(true);
    try {
      const tasks = [
        { label: 'Title', value: form.title },
        { label: 'Summary', value: form.summary },
        { label: 'Content', value: form.content },
      ].filter((t) => t.value.en.trim());

      const results = await batchTranslateI18n(tasks);

      const resultMap: Record<string, I18nText> = {};
      results.forEach((r) => {
        resultMap[r.label] = r.value;
      });

      setForm((prev) => ({
        ...prev,
        title: resultMap.Title || prev.title,
        summary: resultMap.Summary || prev.summary,
        content: resultMap.Content || prev.content,
      }));

      toast.success('Translation completed');
    } catch (err) {
      toast.error('Translation failed: ' + (err instanceof Error ? err.message : String(err)));
    } finally {
      setTranslating(false);
    }
  };

  /* ---------- 封面图上传 ---------- */
  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file');
      return;
    }
    if (file.size > 3 * 1024 * 1024) {
      toast.error('Image must be less than 3MB');
      return;
    }
    try {
      const compressed = await compressImage(file, 1200, 0.72);
      setForm((prev) => ({ ...prev, coverImage: compressed }));
    } catch (err) {
      toast.error('Failed to process image: ' + (err instanceof Error ? err.message : String(err)));
    }
    e.target.value = '';
  };

  /* ---------- 批量翻译 ---------- */
  const handleBatchTranslate = async () => {
    type Task = { label: string; value: I18nText; articleId: string; field: 'title' | 'summary' | 'content' };
    const tasks: Task[] = [];

    articles.forEach((article) => {
      const articleLabel = article.title.en || article.slug;
      tasks.push({ label: `${articleLabel} - Title`, value: article.title, articleId: article.id, field: 'title' });
      tasks.push({ label: `${articleLabel} - Summary`, value: article.summary, articleId: article.id, field: 'summary' });
      tasks.push({ label: `${articleLabel} - Content`, value: article.content, articleId: article.id, field: 'content' });
    });

    const validTasks = tasks.filter((t) => t.value.en.trim());
    if (validTasks.length === 0) {
      toast.warning('No English content found to translate');
      return;
    }

    setBatchTranslating(true);
    setBatchTranslateProgress({ current: 0, total: validTasks.length });
    try {
      const results = await batchTranslateI18n(
        validTasks.map((t) => ({ label: t.label, value: t.value })),
        (cur, total) => setBatchTranslateProgress({ current: cur, total }),
      );

      // 按 article 分组更新
      const updates = new Map<string, Partial<IBlogArticle>>();
      results.forEach((r) => {
        const task = validTasks.find((t) => t.label === r.label);
        if (!task) return;
        const existing = updates.get(task.articleId) || {};
        updates.set(task.articleId, { ...existing, [task.field]: r.value });
      });

      updates.forEach((data, id) => {
        updateArticle(id, data);
      });

      markDirty('blog');
      toast.success(`Batch translation completed: ${results.length} items`);
    } catch (err) {
      toast.error('Batch translation failed: ' + (err instanceof Error ? err.message : String(err)));
    } finally {
      setBatchTranslating(false);
      setBatchTranslateProgress({ current: 0, total: 0 });
    }
  };

  /* ---------- 同步到 GitHub ---------- */
  const handleSync = async () => {
    try {
      const success = await syncModule('blog', 'Blog', async (config) => {
        // 1. 同步封面图
        let dataWithImages = await syncImagesInData(
          config,
          articles,
          'blog',
          ['coverImage' as any]
        );
        // 2. 同步正文中的 base64 图片
        dataWithImages = await Promise.all(
          (dataWithImages as IBlogArticle[]).map(async (article) => {
            const newContent = { ...article.content };
            const langs: Array<'en' | 'zh' | 'es' | 'ja'> = ['en', 'zh', 'es', 'ja'];
            for (const lang of langs) {
              const html = article.content[lang];
              if (html && html.includes('data:image')) {
                newContent[lang] = await syncImagesInHtml(config, html, 'blog');
              }
            }
            return { ...article, content: newContent };
          })
        ) as unknown as typeof dataWithImages;
        await syncJsonFile(
          config,
          'data/blog.json',
          dataWithImages,
          'Update blog data'
        );
      });
      if (success) {
        toast.success('Synced to GitHub successfully');
      } else {
        toast.error('Sync failed');
      }
    } catch (err) {
      toast.error('Sync failed: ' + (err instanceof Error ? err.message : String(err)));
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <PageBreadcrumb
          firstItem={{ label: adminT('admin.dashboard'), href: '/admin' }}
          items={[{ label: adminT('admin.blog') }]}
        />
      </div>

      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">{adminT('admin.blog')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.total')}: {articles.length}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />

          <Button variant="outline" size="sm" onClick={handleSync} disabled={loading}>
            <RefreshCw className="size-4 mr-2" />
            {adminT('admin.syncToGithub')}
          </Button>
          <Button variant="outline" size="sm" onClick={handleBatchTranslate} disabled={batchTranslating || loading}>
            {batchTranslating ? (
              <Loader2 className="size-4 mr-2 animate-spin" />
            ) : (
              <Globe className="size-4 mr-2" />
            )}
            Batch Translate
          </Button>
          <Button size="sm" onClick={openCreate}>
            <Plus className="size-4 mr-2" />
            Add Article
          </Button>
        </div>
      </div>

      {batchTranslating && (
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <Loader2 className="size-5 animate-spin text-primary" />
              <div className="flex-1">
                <div className="text-sm font-medium text-foreground">
                  Translating... {batchTranslateProgress.current} / {batchTranslateProgress.total}
                </div>
                <div className="h-2 bg-muted rounded-full mt-2 overflow-hidden">
                  <div
                    className="h-full bg-primary transition-all duration-300"
                    style={{ width: `${(batchTranslateProgress.current / batchTranslateProgress.total) * 100}%` }}
                  />
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle>Blog Articles</CardTitle>
            <div className="relative w-64">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                type="search"
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setCurrentPage(1);
                }}
                placeholder="Search articles..."
                className="bg-background pl-9"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="whitespace-nowrap">Cover</TableHead>
                  <TableHead className="whitespace-nowrap">Title</TableHead>
                  <TableHead className="whitespace-nowrap">Slug</TableHead>
                  <TableHead className="whitespace-nowrap">Category</TableHead>
                  <TableHead className="whitespace-nowrap">Date</TableHead>
                  <TableHead className="whitespace-nowrap">Status</TableHead>
                  <TableHead className="whitespace-nowrap text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {paginatedArticles.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center py-8 text-muted-foreground">
                      No articles found
                    </TableCell>
                  </TableRow>
                ) : (
                  paginatedArticles.map((article) => (
                    <TableRow key={article.id}>
                      <TableCell>
                        <div className="size-12 rounded border border-border overflow-hidden bg-muted flex items-center justify-center">
                          {article.coverImage ? (
                            <Image
                              src={imgPath(article.coverImage)}
                              alt={article.title.en}
                              className="w-full h-full object-cover"
                            />
                          ) : (
                            <span className="text-xs text-muted-foreground">No img</span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="font-medium">
                        <div className="max-w-[200px] truncate">{article.title.en}</div>
                        <div className="text-xs text-muted-foreground max-w-[200px] truncate">
                          {article.title.zh}
                        </div>
                      </TableCell>
                      <TableCell>
                        <code className="text-xs bg-muted px-1.5 py-0.5 rounded">{article.slug}</code>
                      </TableCell>
                      <TableCell>
                        <span className="text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">
                          {article.category}
                        </span>
                      </TableCell>
                      <TableCell className="whitespace-nowrap text-muted-foreground text-sm">
                        {article.publishDate}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Switch
                            checked={article.published}
                            onCheckedChange={(checked) => togglePublished(article.id, checked)}
                          />
                          <span className={`text-xs ${article.published ? 'text-success' : 'text-muted-foreground'}`}>
                            {article.published ? 'Published' : 'Draft'}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => togglePublished(article.id, !article.published)}
                            title={article.published ? 'Unpublish' : 'Publish'}
                          >
                            {article.published ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => openEdit(article)}
                          >
                            <Edit2 className="size-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => setDeleteId(article.id)}
                            className="text-destructive hover:text-destructive"
                          >
                            <Trash2 className="size-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>

          {totalPages > 1 && (
            <div className="flex items-center justify-end gap-2 p-4 border-t border-border">
              <Button
                variant="outline"
                size="icon"
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="h-8 w-8"
              >
                <ChevronLeft className="size-4" />
              </Button>
              <span className="text-sm text-muted-foreground">
                {currentPage} / {totalPages}
              </span>
              <Button
                variant="outline"
                size="icon"
                onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="h-8 w-8"
              >
                <ChevronRight className="size-4" />
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Edit / Create Dialog */}
      <Dialog open={dialogOpen} onOpenChange={(open) => {
        if (!open) resetForm();
        setDialogOpen(open);
      }}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingId ? 'Edit Article' : 'Add Article'}</DialogTitle>
          </DialogHeader>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Cover Image */}
            <div className="space-y-2">
              <Label>Cover Image</Label>
              <div className="flex items-start gap-4">
                <div className="size-32 border border-border rounded overflow-hidden bg-muted flex items-center justify-center shrink-0">
                  {form.coverImage ? (
                    <Image
                      src={imgPath(form.coverImage)}
                      alt="cover preview"
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <span className="text-xs text-muted-foreground">No image</span>
                  )}
                </div>
                <div className="space-y-2">
                  <Input
                    type="file"
                    accept="image/*"
                    onChange={handleCoverUpload}
                    className="max-w-xs"
                  />
                  <p className="text-xs text-muted-foreground">
                    Recommended: 1200x675, JPG/PNG, under 3MB
                  </p>
                </div>
              </div>
            </div>

            {/* Slug + Category + Date */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="slug">SEO Slug *</Label>
                <Input
                  id="slug"
                  value={form.slug}
                  onChange={(e) => setForm((prev) => ({ ...prev, slug: e.target.value }))}
                  placeholder="how-to-install"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="category">Category</Label>
                <Input
                  id="category"
                  value={form.category}
                  onChange={(e) => setForm((prev) => ({ ...prev, category: e.target.value }))}
                  placeholder="Guide"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="publishDate">Publish Date</Label>
                <Input
                  id="publishDate"
                  type="date"
                  value={form.publishDate}
                  onChange={(e) => setForm((prev) => ({ ...prev, publishDate: e.target.value }))}
                />
              </div>
            </div>

            {/* Title */}
            <div className="space-y-2">
              <Label>Title (4 languages) *</Label>
              <I18nInput
                value={form.title}
                onChange={(val) => setForm((prev) => ({ ...prev, title: val }))}
                placeholder="Article title"
              />
            </div>

            {/* Summary */}
            <div className="space-y-2">
              <Label>Summary (4 languages)</Label>
              <I18nInput
                value={form.summary}
                onChange={(val) => setForm((prev) => ({ ...prev, summary: val }))}
                placeholder="Brief summary of the article"
                multiline
                rows={2}
              />
            </div>

            {/* Content */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label>Content (4 languages, rich text)</Label>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={handleTranslate}
                  disabled={translating}
                >
                  {translating ? (
                    <Loader2 className="size-4 mr-2 animate-spin" />
                  ) : (
                    <Languages className="size-4 mr-2" />
                  )}
                  Translate All
                </Button>
              </div>
              <RichTextEditor
                value={form.content}
                onChange={(val) => setForm((prev) => ({ ...prev, content: val }))}
                placeholder="Write your article content here..."
              />
            </div>

            {/* Published */}
            <div className="flex items-center gap-3">
              <Switch
                id="published"
                checked={form.published}
                onCheckedChange={(checked) => setForm((prev) => ({ ...prev, published: checked }))}
              />
              <Label htmlFor="published">Published</Label>
            </div>

            <DialogFooter className="gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  setDialogOpen(false);
                  resetForm();
                }}
              >
                Cancel
              </Button>
              <Button type="submit">
                {editingId ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Article</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this article? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
